wave_four_data <- loaded_files$wave_four
wave_six_data <- loaded_files$wave_six
wave_eight_data <- loaded_files$wave_eight
wave_nine_data <- loaded_files$wave_nine

# Merge datasets by NSID using full_join
merged_data <- wave_one_data %>%
  full_join(wave_six_data, by = 'NSID') %>%
  full_join(wave_eight_data, by = 'NSID') %>%
  full_join(wave_nine_data, by = 'NSID')

# Define missing value mapping function
map_missing_values <- function(x, metadata) {
  if (is.numeric(x)) {
    x <- ifelse(x %in% metadata$user_missing_values, NA_integer_, x)
  }
  x
}

# Define function to harmonize partnership/marital status
harmonize_partnership_status <- function(x, wave, age) {
  if (is.na(x)) {
    return(NA_integer_)
  }

  # Mapping logic for each wave
  if (wave == 'wave_six' && age == 19) {
    # Wave 6 (Age 19) mapping
    mapping <- c(
      -997.0 = -2, -97.0 = -7, -92.0 = -9, -91.0 = -1, -1.0 = -8,
      1.0 = 1, 2.0 = 2, 3.0 = 3, 4.0 = 4, 5.0 = 5
    )
  } else if (wave == 'wave_eight' && age == 25) {
    # Wave 8 (Age 25) mapping
    mapping <- c(
      -9.0 = -9, -8.0 = -8, -1.0 = -1,
      1.0 = 1, 2.0 = 2, 3.0 = 3, 4.0 = 4, 5.0 = 5,
      6.0 = 2, 7.0 = 3, 8.0 = 4
    )
  } else if (wave == 'wave_nine' && age == 32) {
    # Wave 9 (Age 32) mapping
    mapping <- c(
      -9.0 = -9, -8.0 = -8,
      1.0 = 1, 2.0 = 2, 3.0 = 4, 4.0 = 3, 5.0 = 5,
      6.0 = 2, 7.0 = 4, 8.0 = 5
    )
  } else {
    return(NA_integer_)
  }

  if (x %in% names(mapping)) {
    return(mapping[[as.character(x)]])
  } else {
    return(NA_integer_)
  }
}

# Create age-specific partnership variables
merged_data <- merged_data %>%
  mutate(
    # Age 19 variable
    partnr19 = case_when(
      !is.na(W6MarStatYP) ~ harmonize_partnership_status(W6MarStatYP, 'wave_six', 19),
      TRUE ~ NA_integer_
    ),

    # Age 25 variable (collapsed)
    partnr25 = case_when(
      !is.na(W8DMARSTAT) ~ harmonize_partnership_status(W8DMARSTAT, 'wave_eight', 25),
      TRUE ~ NA_integer_
    ),

    # Age 32 variable
    partnr32 = case_when(
      !is.na(W9DMARSTAT) ~ harmonize_partnership_status(W9DMARSTAT, 'wave_nine', 32),
      TRUE ~ NA_integer_
    )
  )

# Create detailed partnership variables for ages 25 and 32
merged_data <- merged_data %>%
  mutate(
    # Age 25 detailed variable
    partnradu25 = case_when(
      !is.na(W8DMARSTAT) ~ W8DMARSTAT,
      TRUE ~ NA_integer_
    ),

    # Age 32 detailed variable
    partnradu32 = case_when(
      !is.na(W9DMARSTAT) ~ W9DMARSTAT,
      TRUE ~ NA_integer_
    )
  )

# Define value labels for harmonized variables
partnr_value_labels <- labelled::labelled(
  c(
    -9 = 'Refusal',
    -8 = 'Insufficient information',
    -7 = 'Prefer not to say',
    -2 = 'Schedule not applicable / script error',
    -1 = 'Not applicable',
    1 = 'Single, never married',
    2 = 'Married',
    3 = 'Separated',
    4 = 'Divorced',
    5 = 'Widowed'
  )
)

# Apply labels to harmonized variables
merged_data$partnr19 <- labelled::labelled(merged_data$partnr19, partnr_value_labels)
merged_data$partnr25 <- labelled::labelled(merged_data$partnr25, partnr_value_labels)
merged_data$partnr32 <- labelled::labelled(merged_data$partnr32, partnr_value_labels)

# Write output to CSV
write_csv(merged_data, 'data/output/cleaned_data.csv')

# Print confirmation message
message('Cleaned data has been written to data/output/cleaned_data.csv')
"
  }
}
